function drawEeveeFluffyClay(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 6.0;
  const tailSwayY = Math.cos(tailLag) * 3.5;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi chổi lông
  const tx = 18 + tailSwayX;
  const ty = by - 2 + tailSwayY;
  ctx.fillStyle = '#b45309';
  ctx.beginPath(); ctx.ellipse(tx - 2, ty - 2, 14, 24, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.moveTo(tx + 4, ty - 18); ctx.lineTo(tx + 14, ty - 32); ctx.lineTo(tx - 4, ty - 22); ctx.fill();
  ctx.beginPath(); ctx.ellipse(tx + 4, ty - 22, 8, 10, 0, 0, Math.PI * 2); ctx.fill();

  // Thân & chân
  ctx.fillStyle = '#b45309';
  ctx.beginPath(); ctx.ellipse(0, by + 16, 16 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-16, by + 26, 7, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-7,  by + 26, 7, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(2,   by + 26, 7, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(11,  by + 26, 7, 12, 3); ctx.fill();

  // Bờm cổ kem xốp
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.arc(-14, by + 7, 9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(14,  by + 7, 9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0,   by + 11, 10, 0, Math.PI * 2); ctx.fill();

  // Đầu nâu
  ctx.fillStyle = '#b45309';
  ctx.beginPath(); ctx.ellipse(0, by - 10, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai cáo
  ctx.beginPath(); ctx.moveTo(-14, by - 20); ctx.lineTo(-32, by - 48); ctx.lineTo(-4, by - 24); ctx.fill();
  ctx.beginPath(); ctx.moveTo(4,   by - 24); ctx.lineTo(32,  by - 48); ctx.lineTo(14, by - 20); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.moveTo(-15, by - 22); ctx.lineTo(-28, by - 44); ctx.lineTo(-8, by - 26); ctx.fill();
  ctx.beginPath(); ctx.moveTo(8,   by - 26); ctx.lineTo(28,  by - 44); ctx.lineTo(15, by - 22); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.ellipse(-9, by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(9,  by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-10, by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(8,   by - 13, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-3, by - 2); ctx.lineTo(0, by - 1); ctx.lineTo(3, by - 2);
  ctx.stroke();

  ctx.restore();
}
